    let calls = 0;
    const result = await discoverInvestors({
      fetchImpl: async () => {
        calls += 1;
        // Always 429 — exhausts retries then surfaces the honest error.
        return new Response('rate limited', { status: 429 });
      },
      delayMs: 0,
    });
